  function makeGame(g){const centered=['drift','rocket','mech','skyhook'].includes(g.id)?2:1;return {id:g.id,t:0,score:0,lives:3,level:1,spawn:0,objects:[],particles:[],player:centered,polarity:1,combo:0,bestCombo:0,bossKills:0,angle:1,shield:'',ball:{x:210,y:430,vx:120,vy:-180},flipperCooldown:[0,0],flipperPose:[0,0],water:535,sequence:[],input:[],target:[],code:[],dials:[0,0,0],dial:0,gravity:0,grid:null,cell:0,cooldown:0,flash:0,shake:0,drift:0,driftCooldown:0,charge:0,streak:0,energy:0,boost:0,sector:1,boss:null,nextBossAt:10,ended:false,seed:Math.floor(Math.random()*999999)};}
