  function beatInput(direction,a){if(!a.target?.length)return;const expected=a.target[0];if(direction===expected){a.target.shift();a.score+=12+a.level;a.combo++;a.bestCombo=Math.max(a.bestCombo,a.combo);a.energy=Math.min(100,a.energy+3);a.cooldown=Math.max(.62,1.35-a.level*.07);if(!a.target.length){a.score+=25+a.combo*6;newBeat(a)}}else{a.combo=0;hurt(a)}}
  function echoInput(direction,a){if(!a.sequence?.length)return;const expected=a.sequence[a.input.length];if(direction===expected){a.input.push(direction);a.score+=5;if(a.input.length===a.sequence.length){a.score+=35+a.level*5;a.streak++;a.combo++;a.bestCombo=Math.max(a.bestCombo,a.combo);a.energy=Math.min(100,a.energy+9);newEcho(a)}}else{hurt(a);a.input=[];a.streak=0;newEcho(a)}}
  function newBeat(a){const dirs=['north','south','east','west'];a.target=Array.from({length:Math.min(6,2+Math.floor(a.level/2))},()=>pick(dirs));a.cooldown=Math.max(.62,1.35-a.level*.07)}
  function newEcho(a){const dirs=['north','south','east','west'];a.sequence=Array.from({length:Math.min(9,3+a.streak+Math.floor(a.level/3))},()=>pick(dirs));a.input=[];a.reveal=0;a.showing=true;a.echoInterval=Math.max(.34,.85-a.level*.025);a.inputDeadline=Math.max(2.2,5-a.level*.2)}
  function newLock(a){const length=Math.min(5,3+Math.floor((a.puzzlesSolved||0)/2));a.code=[];while(a.code.length<length){const digit=Math.floor(Math.random()*10);if(!a.code.includes(digit))a.code.push(digit)}a.dials=Array(length).fill(0);a.dial=0;a.lockMistakes=0;a.hint='';}
  function spawnPuzzle(id,a){if(id==='circuit'||id==='gravity')newGrid(a,id);if(id==='echo')newEcho(a);if(id==='beat')newBeat(a);if(id==='lockpick')newLock(a);if(id==='flood'){a.water=565;a.jumpReady=true;a.jumpCooldown=0;a.jumpY=0;a.jumpVy=0;a.floodDamageCooldown=0}if(id==='skyhook'){a.hookPhase=0;a.hookAttempted=false;a.hookTargetLane=2;a.climbs=0}if(id==='rocket'){a.altitude=48;a.fuel=100;a.rescues=0;a.crashTimer=0}}
