    if(a.id==='bumper'){roundRect(c,44,90,332,480,45,'#17213b','#8798c633');for(const o of a.objects)if(o.kind==='bumper')circle(c,o.x,o.y,o.r,'#70dcff',15);const b=a.ball;circle(c,b.x,b.y,12,'#fff6b1',18);circle(c,b.x-3,b.y-4,4,'#fff');drawFlipper(c,130,530,0,a.flipperPose[0]);drawFlipper(c,290,530,1,a.flipperPose[1]);drawText(c,'FLIPPER',130,552,9,'#bac5e3');drawText(c,'FLIPPER',290,552,9,'#bac5e3')}
