    if(a.id==='circuit'||a.id==='gravity'){drawGrid(c,a);if(a.id==='gravity'){const n=a.size||4;drawText(c,'●',55+(a.ballLane+.5)*310/n,148,20,'#ffe16c');drawText(c,'SORTIE  '+String.fromCharCode(65+a.goalLane),55+(a.goalLane+.5)*310/n,555,11,selected.color);drawText(c,'CHOISIS UNE COLONNE · LANCE',210,515,10,'#c5d1ef')}}
    if(a.id==='echo'){roundRect(c,35,140,350,340,25,'#171e37','#ffffff20');if(a.showing){const j=Math.floor(a.reveal/a.echoInterval);const d=a.sequence[j];if(d)drawEchoSymbol(c,d,selected.color);drawText(c,'MÉMORISE LA SÉQUENCE',210,200,13,'#b7c3e2');drawText(c,Math.min(j+1,a.sequence.length)+' / '+a.sequence.length,210,490,15,selected.color)}else{['north','east','south','west'].forEach((d,i)=>{const x=115+(i%2)*190,y=315+Math.floor(i/2)*105;roundRect(c,x-48,y-38,96,76,18,'#293555','#ffffff21');drawText(c,['↑','→','↓','←'][i],x,y,26,'#eff3ff')});drawText(c,(a.input||[]).length+' / '+a.sequence.length,210,490,15,selected.color)}}
