  function drawShip(c,x,y,type,color){c.save();c.translate(x,y);c.shadowColor=color;c.shadowBlur=22;const s=type==='robot'?1.22:1;c.fillStyle=color;c.strokeStyle='#f5f7ff';c.lineWidth=2;c.beginPath();if(type==='rocket'){c.moveTo(0,-27*s);c.lineTo(15*s,-2);c.lineTo(12*s,17*s);c.lineTo(0,11*s);c.lineTo(-12*s,17*s);c.lineTo(-15*s,-2)}else if(type==='robot'){c.roundRect(-18*s,-19*s,36*s,39*s,8)}else if(type==='climber'){c.arc(0,0,15*s,0,Math.PI*2)}else{c.moveTo(0,-23*s);c.lineTo(19*s,15*s);c.lineTo(0,9*s);c.lineTo(-19*s,15*s)}c.closePath();c.fill();c.stroke();c.shadowBlur=0;c.fillStyle='#e8f5ff';c.beginPath();c.ellipse(0,-3*s,5*s,7*s,0,0,Math.PI*2);c.fill();c.fillStyle='#15203a';c.fillRect(-6*s,4*s,12*s,5*s);if(type==='rocket'){c.fillStyle='#ffce71';c.beginPath();c.moveTo(-5,-19);c.lineTo(0,-31-rnd(0,10));c.lineTo(5,-19);c.fill()}c.restore()}
  function drawFlipper(c,x,y,side,pulse){c.save();c.translate(x,y);c.rotate(side?.24-pulse*1.45:-.24+pulse*1.45);roundRect(c,-46,-7,92,14,7,side?'#ff91a6':'#ff7896','#ffe4e8');circle(c,side?-43:43,0,8,'#ffe8b1',8);c.restore()}
  function drawGrid(c,a){const n=a.size||4,size=310/n,x0=55,y0=170;c.save();for(let y=0;y<n;y++)for(let x=0;x<n;x++){const t=a.grid[y*n+x],x1=x0+x*size,y1=y0+y*size;roundRect(c,x1+2,y1+2,size-4,size-4,8,(x+y)%2?'#202b49':'#1b2642',x*n+y===a.cell?selected.color:'#ffffff17');c.save();c.translate(x1+size/2,y1+size/2);c.rotate(t.rot*Math.PI/2);c.strokeStyle=t.solid?'#ff7189':(x===0&&y===0)||(x===n-1&&y===n-1)?selected.color:'#9cb3de';c.lineWidth=7;c.lineCap='round';if(t.solid){c.beginPath();c.moveTo(-size*.19,-size*.19);c.lineTo(size*.19,size*.19);c.moveTo(size*.19,-size*.19);c.lineTo(-size*.19,size*.19);c.stroke()}else if(t.type==='line'){c.beginPath();c.moveTo(0,-size*.25);c.lineTo(0,size*.25);c.stroke()}else if(t.type==='elbow'){c.beginPath();c.moveTo(0,-size*.25);c.lineTo(0,0);c.lineTo(size*.25,0);c.stroke()}else{c.beginPath();c.moveTo(0,-size*.25);c.lineTo(0,size*.2);c.moveTo(0,0);c.lineTo(size*.22,0);c.stroke()}c.restore()}c.restore();if(a.id==='circuit'){drawText(c,'SOURCE',86,157,10,'#bfe9ff');drawText(c,'SORTIE',334,y0+size*n+17,10,'#bfe9ff')}drawText(c,'TEMPS '+Math.ceil(a.puzzleClock)+' s',210,130,11,a.puzzleClock<5?'#ff7189':'#d5ddf7');drawText(c,a.id==='circuit'?'TAPE POUR TOURNER':'GRAVITÉ '+['↓','←','↑','→'][a.gravity||0],210,540,14,selected.color)}
  function drawEchoSymbol(c,d,color){const map={north:'↑',south:'↓',east:'→',west:'←'};circle(c,210,335,60,color,25);drawText(c,map[d],210,335,50,'#13192d')}
  function drawPreview(g){game=makeGame(g);spawnPuzzle(g.id,game);draw(game)}
  function sound(kind){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),gain=audio.createGain(),now=audio.currentTime,f=kind==='hit'?115:kind==='boost'?520:kind==='start'?330:kind==='score'?690:260;o.type=kind==='hit'?'sawtooth':'triangle';o.frequency.setValueAtTime(f,now);o.frequency.exponentialRampToValueAtTime(kind==='hit'?65:f*1.42,now+.11);gain.gain.setValueAtTime(kind==='hit'?.04:.025,now);gain.gain.exponentialRampToValueAtTime(.001,now+.13);o.connect(gain);gain.connect(audio.destination);o.start(now);o.stop(now+.14)}catch(_){}}
  function toggleSound(){soundOn=!soundOn;const b=root.querySelector('[data-sound]');b.textContent=soundOn?'♫ SON':'♫ MUET';b.setAttribute('aria-pressed',String(soundOn));if(soundOn)sound('start')}
  function pause(){if(scene==='playing'){scene='paused';cancelAnimationFrame(raf);overlay.hidden=false;overlay.innerHTML='<div class="lab-overlay-card"><div class="big">Ⅱ</div><h2>Pause</h2><p>Ta partie reprend exactement où tu l’as laissée.</p><button class="lab-again" data-resume>Reprendre&nbsp; ▶</button></div>';overlay.querySelector('[data-resume]').addEventListener('click',()=>{overlay.hidden=true;scene='playing';last=performance.now();raf=requestAnimationFrame(loop)})}}
  function keydown(e){if(e.key==='Escape'){e.preventDefault();pause();return}const compass=['parry','beat','echo'].includes(game?.id),map={ArrowLeft:compass?'west':'left',ArrowRight:compass?'east':'right',ArrowUp:'north',ArrowDown:'south',' ':'primary',Enter:'primary',a:compass?'west':'left',d:compass?'east':'right',w:'north',s:'south',Shift:'boost'};const action=map[e.key];if(action){e.preventDefault();act(action)}}
  function boot(){shell();document.addEventListener('keydown',keydown);}
  globalThis.RivoGameLab=Object.freeze({boot,catalog:()=>games.map(({id,name,type,tag})=>({id,name,type,tag}))});
